std::span<const ParityRow> maya_parity_rows() noexcept {
  return {kMayaRows};
}

const ParityRow* maya_parity_row(std::string_view key) noexcept {
  for (const auto& row : kMayaRows) {
    if (row.key == key) return &row;
  }
  return nullptr;
}

